// cursor (their data export).
func (q *Queries) UserMessagesAfter(ctx context.Context, arg UserMessagesAfterParams) ([]UserMessagesAfterRow, error) {
	rows, err := q.db.Query(ctx, userMessagesAfter, arg.AuthorID, arg.After, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserMessagesAfterRow
	for rows.Next() {
		var i UserMessagesAfterRow
		if err := rows.Scan(
			&i.ID,
			&i.ChannelID,
			&i.ChannelName,
			&i.RootID,
			&i.Body,
			&i.CreatedAt,
			&i.EditedAt,
			&i.DeletedAt,
			&i.HasFiles,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

